class A{constructor(e){this.size=e,this.cosTable=new Float32Array(e/2),this.sinTable=new Float32Array(e/2);for(let o=0;o<e/2;o++)this.cosTable[o]=Math.cos(-2*Math.PI*o/e),this.sinTable[o]=Math.sin(-2*Math.PI*o/e);this.window=new Float32Array(e);for(let o=0;o<e;o++)this.window[o]=.5*(1-Math.cos(2*Math.PI*o/(e-1)))}process(e){const o=this.size,s=new Float32Array(o),l=new Float32Array(o);for(let t=0;t<o;t++)s[t]=(e[t]||0)*this.window[t];let c=0;for(let t=0;t<o-1;t++){if(t<c){let i=s[t];s[t]=s[c],s[c]=i}let a=o>>1;for(;a<=c;)c-=a,a>>=1;c+=a}for(let t=2;t<=o;t<<=1){const a=t>>1,i=o/t;for(let n=0;n<o;n+=t){let h=0;for(let r=0;r<a;r++){const f=this.cosTable[h],M=this.sinTable[h],m=s[n+r+a]*f-l[n+r+a]*M,F=s[n+r+a]*M+l[n+r+a]*f;s[n+r+a]=s[n+r]-m,l[n+r+a]=l[n+r]-F,s[n+r]+=m,l[n+r]+=F,h+=i}}}const w=new Uint8Array(o/2),b=-85,T=-15-b;for(let t=0;t<o/2;t++){const a=Math.sqrt(s[t]*s[t]+l[t]*l[t])/(o/2),i=20*Math.log10(a+1e-6),n=Math.max(0,Math.min(1,(i-b)/T));w[t]=Math.round(n*255)}return w}}export{A as FastFourierTransformer};
